    42  static void
    43  removeSecureChannelCallback(void *_, channel_entry *entry) {
    44      UA_SecureChannel_deleteMembersCleanup(&entry->channel);
    45  }
    46
    47  static void
    48  removeSecureChannel(UA_SecureChannelManager *cm, channel_entry *entry) {
    49      /* Detach the channel and make the capacity available */
    50      TAILQ_REMOVE(&cm->channels, entry, pointers);
    51      UA_atomic_subUInt32(&cm->currentChannelCount, 1);
    52
    53      /* Add a delayed callback to remove the channel when the currently
    54       * scheduled jobs have completed */
    55      entry->cleanupCallback.callback = (UA_ApplicationCallback)removeSecureChannelCallback;
    56      entry->cleanupCallback.application = NULL;
    57      entry->cleanupCallback.data = entry;
    58      UA_WorkQueue_enqueueDelayed(&cm->server->workQueue, &entry->cleanupCallback);
    59  }
