    61  /* remove channels that were not renewed or who have no connection attached */
    62  void
    63  UA_SecureChannelManager_cleanupTimedOut(UA_SecureChannelManager *cm, UA_DateTime nowMonotonic) {
    64      channel_entry *entry, *temp;
    65      TAILQ_FOREACH_SAFE(entry, &cm->channels, pointers, temp) {
    66          UA_DateTime timeout = entry->channel.securityToken.createdAt +
    67                                (UA_DateTime)(entry->channel.securityToken.revisedLifetime * UA_DATETIME_MSEC);
    68          if(timeout < nowMonotonic || !entry->channel.connection) {
    69              UA_LOG_INFO_CHANNEL(cm->server->config.logger, &entry->channel,
    70                                  "SecureChannel has timed out");
    71              removeSecureChannel(cm, entry);
    72          } else if(entry->channel.nextSecurityToken.tokenId > 0) {
    73              UA_SecureChannel_revolveTokens(&entry->channel);
    74          }
    75      }
    76  }
    77
    78  /* remove the first channel that has no session attached */
    79  static UA_Boolean
    80  purgeFirstChannelWithoutSession(UA_SecureChannelManager *cm) {
    81      channel_entry *entry;
    82      TAILQ_FOREACH(entry, &cm->channels, pointers) {
    83          if(LIST_EMPTY(&entry->channel.sessions)) {
    84              UA_LOG_INFO_CHANNEL(cm->server->config.logger, &entry->channel,
    85                                  "Channel was purged since maxSecureChannels was "
    86                                  "reached and channel had no session attached");
    87              removeSecureChannel(cm, entry);
    88              return true;
    89          }
    90      }
    91      return false;
    92  }
