    94  UA_StatusCode
    95  UA_SecureChannelManager_create(UA_SecureChannelManager *const cm, UA_Connection *const connection,
    96                                 const UA_SecurityPolicy *const securityPolicy,
    97                                 const UA_AsymmetricAlgorithmSecurityHeader *const asymHeader) {
    98      /* connection already has a channel attached. */
    99      if(connection->channel != NULL)
   100          return UA_STATUSCODE_BADINTERNALERROR;
   101
   102      /* Check if there exists a free SC, otherwise try to purge one SC without a
   103       * session the purge has been introduced to pass CTT, it is not clear what
   104       * strategy is expected here */
   105      if(cm->currentChannelCount >= cm->server->config.maxSecureChannels &&
   106         !purgeFirstChannelWithoutSession(cm))
   107          return UA_STATUSCODE_BADOUTOFMEMORY;
   108
   109      UA_LOG_INFO(cm->server->config.logger, UA_LOGCATEGORY_SECURECHANNEL,
   110                  "Creating a new SecureChannel");
   111
   112      channel_entry *entry = (channel_entry *)UA_malloc(sizeof(channel_entry));
   113      if(!entry)
   114          return UA_STATUSCODE_BADOUTOFMEMORY;
   115
   116      /* Create the channel context and parse the sender (remote) certificate used for the
   117       * secureChannel. */
   118      UA_SecureChannel_init(&entry->channel);
   119      UA_StatusCode retval =
   120          UA_SecureChannel_setSecurityPolicy(&entry->channel, securityPolicy,
   121                                             &asymHeader->senderCertificate);
   122      if(retval != UA_STATUSCODE_GOOD) {
   123          UA_free(entry);
   124          return retval;
   125      }
   126
   127      /* Channel state is fresh (0) */
   128      entry->channel.securityToken.channelId = 0;
   129      entry->channel.securityToken.tokenId = cm->lastTokenId++;
   130      entry->channel.securityToken.createdAt = UA_DateTime_now();
