    15  UA_StatusCode
    16  UA_SessionManager_init(UA_SessionManager *sm, UA_Server *server) {
    17      LIST_INIT(&sm->sessions);
    18      sm->currentSessionCount = 0;
    19      sm->server = server;
    20      return UA_STATUSCODE_GOOD;
    21  }
