    23  void UA_SessionManager_deleteMembers(UA_SessionManager *sm) {
    24      session_list_entry *current, *temp;
    25      LIST_FOREACH_SAFE(current, &sm->sessions, pointers, temp) {
    26          LIST_REMOVE(current, pointers);
    27          UA_Session_deleteMembersCleanup(&current->session, sm->server);
    28          UA_free(current);
    29      }
    30  }
