    59  void
    60  UA_SessionManager_cleanupTimedOut(UA_SessionManager *sm,
    61                                    UA_DateTime nowMonotonic) {
    62      session_list_entry *sentry, *temp;
    63      LIST_FOREACH_SAFE(sentry, &sm->sessions, pointers, temp) {
    64          /* Session has timed out? */
    65          if(sentry->session.validTill >= nowMonotonic)
    66              continue;
    67          UA_LOG_INFO_SESSION(sm->server->config.logger, &sentry->session,
    68                              "Session has timed out");
    69          sm->server->config.accessControl.closeSession(sm->server,
    70                                                        &sm->server->config.accessControl,
    71                                                        &sentry->session.sessionId,
    72                                                        sentry->session.sessionHandle);
    73          removeSession(sm, sentry);
    74      }
    75  }
