    77  UA_Session *
    78  UA_SessionManager_getSessionByToken(UA_SessionManager *sm, const UA_NodeId *token) {
    79      session_list_entry *current = NULL;
    80      LIST_FOREACH(current, &sm->sessions, pointers) {
    81          /* Token does not match */
    82          if(!UA_NodeId_equal(&current->session.header.authenticationToken, token))
    83              continue;
    84
    85          /* Session has timed out */
    86          if(UA_DateTime_nowMonotonic() > current->session.validTill) {
    87              UA_LOG_INFO_SESSION(sm->server->config.logger, &current->session,
    88                                  "Client tries to use a session that has timed out");
    89              return NULL;
    90          }
    91
    92          /* Ok, return */
    93          return &current->session;
    94      }
    95
    96      /* Session not found */
    97      UA_String nodeIdStr = UA_STRING_NULL;
    98      UA_NodeId_toString(token, &nodeIdStr);
    99      UA_LOG_INFO(sm->server->config.logger, UA_LOGCATEGORY_SESSION,
   100                  "Try to use Session with token %.*s but is not found",
   101                  (int)nodeIdStr.length, nodeIdStr.data);
   102      UA_String_deleteMembers(&nodeIdStr);
   103      return NULL;
   104  }
