    92  void UA_Session_addSubscription(UA_Session *session, UA_Subscription *newSubscription) {
    93      newSubscription->subscriptionId = ++session->lastSubscriptionId;
    94
    95      LIST_INSERT_HEAD(&session->serverSubscriptions, newSubscription, listEntry);
    96      session->numSubscriptions++;
    97  }
