    99  UA_StatusCode
   100  UA_Session_deleteSubscription(UA_Server *server, UA_Session *session,
   101                                UA_UInt32 subscriptionId) {
   102      UA_Subscription *sub = UA_Session_getSubscriptionById(session, subscriptionId);
   103      if(!sub)
   104          return UA_STATUSCODE_BADSUBSCRIPTIONIDINVALID;
   105
   106      UA_Subscription_deleteMembers(server, sub);
   107
   108      /* Add a delayed callback to remove the subscription when the currently
   109       * scheduled jobs have completed. There is no actual delayed callback. Just
   110       * free the structure. */
   111      sub->delayedFreePointers.callback = NULL;
   112      UA_WorkQueue_enqueueDelayed(&server->workQueue, &sub->delayedFreePointers);
   113
   114      /* Remove from the session */
   115      LIST_REMOVE(sub, listEntry);
   116      UA_assert(session->numSubscriptions > 0);
   117      session->numSubscriptions--;
   118      return UA_STATUSCODE_GOOD;
   119  }
