   121  UA_Subscription *
   122  UA_Session_getSubscriptionById(UA_Session *session, UA_UInt32 subscriptionId) {
   123      UA_Subscription *sub;
   124      LIST_FOREACH(sub, &session->serverSubscriptions, listEntry) {
   125          if(sub->subscriptionId == subscriptionId)
   126              break;
   127      }
   128      return sub;
   129  }
