   242  UA_Server *
   243  UA_Server_new(const UA_ServerConfig *config) {
   244      /* A config is required */
   245      if(!config)
   246          return NULL;
   247
   248      /* Allocate the server */
   249      UA_Server *server = (UA_Server *)UA_calloc(1, sizeof(UA_Server));
   250      if(!server)
   251          return NULL;
   252
   253      /* Set the config */
   254      server->config = *config;
   255
   256      /* Init start time to zero, the actual start time will be sampled in
   257       * UA_Server_run_startup() */
   258      server->startTime = 0;
   259
   260      /* Set a seed for non-cyptographic randomness */
   261  #ifndef UA_ENABLE_DETERMINISTIC_RNG
   262      UA_random_seed((UA_UInt64)UA_DateTime_now());
   263  #endif
   264
   265      /* Initialize the handling of repeated callbacks */
   266      UA_Timer_init(&server->timer);
   267
   268      UA_WorkQueue_init(&server->workQueue);
   269
   270      /* Initialize the adminSession */
   271      UA_Session_init(&server->adminSession);
   272      server->adminSession.sessionId.identifierType = UA_NODEIDTYPE_GUID;
   273      server->adminSession.sessionId.identifier.guid.data1 = 1;
   274      server->adminSession.validTill = UA_INT64_MAX;
   275
   276      /* Create Namespaces 0 and 1 */
   277      server->namespaces = (UA_String *)UA_Array_new(2, &UA_TYPES[UA_TYPES_STRING]);
   278      server->namespaces[0] = UA_STRING_ALLOC("http://opcfoundation.org/UA/");
   279      UA_String_copy(&server->config.applicationDescription.applicationUri, &server->namespaces[1]);
   280      server->namespacesSize = 2;
   281
   282      /* Initialized SecureChannel and Session managers */
   283      UA_SecureChannelManager_init(&server->secureChannelManager, server);
   284      UA_SessionManager_init(&server->sessionManager, server);
